    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   * Preserves immutability with copy.
   */
  def withMetadata(newMetadata: (String, Any)*): Token =
    copy(metadata = metadata ++ newMetadata)
}

/**
 * Mutable batch of tokens for accumulation during processing.
 * Used for performance-sensitive batch operations.
 */
final class MutableTokenBatch {
  private var tokens: immutable.Vector[Token] = immutable.Vector.empty
  private var processed: Boolean = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def getTokens: immutable.Vector[Token] = tokens.view.force

  def isProcessed: Boolean = processed
}

