/**
 * Covariant container - can return subtypes.
 * The [+T] notation means this container is covariant in T.
 */
final class TokenContainer[+T](items: Seq[T]) {
  private val _items: immutable.Vector[T] = items.toVector

  def getAll: immutable.Vector[T] = _items

  def mapTokens[U](func: T => String): immutable.Vector[String] =
    _items.map(func)
}

/**
 * Contravariant sink - can accept supertypes.
 * The [-T] notation means this sink is contravariant in T.
 */
final class TokenSink[-T] {
  private var received: immutable.Vector[Any] = immutable.Vector.empty

  def receive(item: T): Unit = {
    received = received :+ item
