final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: TokenizableValue): Token = value match {
    case TokenizableValue.NullValue() =>
      Token("NULL", TokenType.Null)

    case TokenizableValue.StructuredValue(tokenStr) =>
      Token(tokenStr, TokenType.Structured)

    case TokenizableValue.StringValue(str) =>
      stringTokenizer.tokenize(str)

    case TokenizableValue.BytesValue(bytes) =>
      stringTokenizer.tokenizeBytes(bytes)

    case TokenizableValue.IntValue(int) =>
      numericTokenizer.tokenizeInt(int)

    case TokenizableValue.DoubleValue(double) =>
      numericTokenizer.tokenizeDouble(double)

    case TokenizableValue.BigDecimalValue(bd) =>
      numericTokenizer.tokenizeBigDecimal(bd)

    case TokenizableValue.DateTimeValue(dt) =>
      temporalTokenizer.tokenizeDateTime(dt)

    case TokenizableValue.DateValue(d) =>
      temporalTokenizer.tokenizeDate(d)

    case TokenizableValue.FallbackValue(any) =>
      Token(any.toString, TokenType.String, Map("fallback" -> true))
  }

  /**
   * Convenience method to tokenize Any value with reflection-free type checking.
   */
  def tokenizeAny(value: Any): Token = {
    val tokenizableValue = value match {
      case null => TokenizableValue.NullValue()
      case s: String => TokenizableValue.StringValue(s)
      case b: Array[Byte] => TokenizableValue.BytesValue(b)
      case i: Int => TokenizableValue.IntValue(i)
      case d: Double => TokenizableValue.DoubleValue(d)
      case bd: BigDecimal => TokenizableValue.BigDecimalValue(bd)
      case dt: LocalDateTime => TokenizableValue.DateTimeValue(dt)
      case d: LocalDate => TokenizableValue.DateValue(d)
      case other => TokenizableValue.FallbackValue(other)
    }
    tokenize(tokenizableValue)
  }
}

// ============================================================================
// Generic Registry with Nested Types
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Demonstrates proper handling of mutable collections in Scala.
 */
final class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: immutable.Vector[T => Option[Token]] = immutable.Vector.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry = registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers = handlers :+ handler
  }

  def process(key: String): immutable.Vector[Option[Token]] = {
    registry.get(key).map { container =>
      container.getAll.map { item =>
        handlers.iterator.map(handler => handler(item)).find(_.isDefined).flatten
