trait Monad[M[_]] extends Functor[M] {
  def pure[A](a: A): M[A]
  def flatMap[A, B](ma: M[A])(f: A => M[B]): M[B]
}

object Monad {
  implicit val optionMonad: Monad[Option] = new Monad[Option] {
    def pure[A](a: A): Option[A] = Some(a)
    def flatMap[A, B](ma: Option[A])(f: A => Option[B]): Option[B] = ma.flatMap(f)
    def map[A, B](fa: Option[A])(f: A => B): Option[B] = fa.map(f)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Fundamental operation for NLP and text processing.
 * Demonstrates iterative processing with metadata tracking.
 */
final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  /**
   * Process a single word into a token string.
   * Returns Option for missing/filtered tokens.
   */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed
        .dropWhile(punctuation.contains)
        .reverse
        .dropWhile(punctuation.contains)
        .reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase()
    }

    if (processed.length < minLength) {
      None
    } else {
      val truncated = maxLength
        .map(max => if (processed.length > max) processed.take(max) else processed)
        .getOrElse(processed)

      if (truncated.nonEmpty) Some(truncated) else None
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): immutable.Vector[Token] = {
    val words = text.split("\\s+").iterator
    var position = 0
    val builder = immutable.Vector.newBuilder[Token]

    for (word <- words) {
      processToken(word).foreach { processed =>
        val token = Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map(
            "position" -> position,
            "original" -> word
          )
        )
        builder += token
        position += 1
      }
    }

    builder.result()
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): immutable.Vector[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): immutable.Vector[(String, Int, Int)] = {
    val builder = immutable.Vector.newBuilder[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        builder += ((processed, start, end))
      }

      currentPos = end
    }

    builder.result()
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int =
    tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 * Uses self type to enable proper method chaining with generics.
 */
final class TokenizerBuilder[T] {
  private var normalizers: immutable.Vector[String => String] = immutable.Vector.empty
  private var validators: immutable.Vector[T => Boolean] = immutable.Vector.empty
  private var metadataMap: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): this.type = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): this.type = {
    validators = validators :+ validator
    this
  }

  def withMetadata(newMetadata: (String, Any)*): this.type = {
    metadataMap = metadataMap ++ newMetadata
    this
  }

  /**
   * Build the final tokenizer function.
   * Returns a function that validates, converts to string, and normalizes.
   */
  def build: T => Either[String, Token] = { value =>
    // Validate
    val validationResult = validators.iterator.find(!_.apply(value))
    if (validationResult.isDefined) {
      Left(s"Validation failed for $value")
    } else {
      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- normalizers) {
        strValue = normalizer(strValue)
      }

      Right(Token(strValue, TokenType.String, metadataMap))
    }
  }
}

