 * Returns lazy iterator for memory efficiency.
 */
def tokenizeBatch(tokenizer: BaseTokenizer[_], values: Iterable[Any]): Iterator[Token] = {
  // Note: In practice, specific tokenizer would be selected based on value type
  values.iterator.map {
    case s: String => tokenize(s)
    case i: Int => tokenize(i)
    case d: Double => tokenize(d)
    case other => tokenize(other)
  }
}

/**
 * Helper to convert a value to a Token using a specific tokenizer.
 */
def toToken[T](tokenizer: BaseTokenizer[T])(value: T): Token =
  tokenizer.tokenize(value)

/**
 * Helper to create a token with metadata.
 */
def withMetadata(token: Token, metadata: (String, Any)*): Token =
  token.withMetadata(metadata: _*)

