/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This Scala translation demonstrates:
 * - Sealed trait hierarchies for exhaustive pattern matching
 * - Case classes for immutable data representation
 * - Generic traits with covariance/contravariance
 * - Type class patterns for extensible dispatch
 * - Scala's standard library (scala.math.BigDecimal, java.time.*)
 * - Option and Either for error handling instead of nulls/exceptions
 * - Functional composition and higher-order functions
 */

import scala.collection.immutable
import scala.math.BigDecimal
import scala.util.{Try, Success, Failure}
import scala.reflect.ClassTag
import java.time.{LocalDate, LocalDateTime}
