  def tokenize(value: TokenizableValue): Token = value match {
    case TokenizableValue.NullValue() =>
      Token("NULL", TokenType.Null)

    case TokenizableValue.StructuredValue(tokenStr) =>
      Token(tokenStr, TokenType.Structured)

    case TokenizableValue.StringValue(str) =>
      stringTokenizer.tokenize(str)

    case TokenizableValue.BytesValue(bytes) =>
      stringTokenizer.tokenizeBytes(bytes)

    case TokenizableValue.IntValue(int) =>
