/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This Scala translation demonstrates:
 * - Sealed trait hierarchies for exhaustive pattern matching
 * - Case classes for immutable data representation
 * - Generic traits with covariance/contravariance
 * - Type class patterns for extensible dispatch
 * - Scala's standard library (scala.math.BigDecimal, java.time.*)
 * - Option and Either for error handling instead of nulls/exceptions
 * - Functional composition and higher-order functions
 */

import scala.collection.immutable
import scala.math.BigDecimal
import scala.util.{Try, Success, Failure}
import scala.reflect.ClassTag
import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.io.Codec

// ============================================================================
// Token Type Enum (Sealed Trait for exhaustive pattern matching)
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType {
    val value = "string"
  }
  case object Numeric extends TokenType {
    val value = "numeric"
  }
  case object Temporal extends TokenType {
    val value = "temporal"
  }
  case object Structured extends TokenType {
    val value = "structured"
  }
  case object Binary extends TokenType {
    val value = "binary"
  }
  case object Null extends TokenType {
    val value = "null"
  }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 * Uses case class for structural equality and copy support.
 */
final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   * Preserves immutability with copy.
   */
  def withMetadata(newMetadata: (String, Any)*): Token =
    copy(metadata = metadata ++ newMetadata)
}

/**
 * Mutable batch of tokens for accumulation during processing.
 * Used for performance-sensitive batch operations.
 */
final class MutableTokenBatch {
  private var tokens: immutable.Vector[Token] = immutable.Vector.empty
  private var processed: Boolean = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new IllegalStateException("Batch already processed")
    }
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def getTokens: immutable.Vector[Token] = tokens

  def isProcessed: Boolean = processed
}

// ============================================================================
// Generic Container Classes (Variance)
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * The [+T] notation means this container is covariant in T.
 */
final class TokenContainer[+T](items: Seq[T]) {
  private val _items: immutable.Vector[T] = items.toVector

  def getAll: immutable.Vector[T] = _items

  def mapTokens[U](func: T => String): immutable.Vector[String] =
    _items.map(func)
}

/**
 * Contravariant sink - can accept supertypes.
 * The [-T] notation means this sink is contravariant in T.
 */
final class TokenSink[-T] {
  private var received: immutable.Vector[Any] = immutable.Vector.empty

  def receive(item: T): Unit = {
    received = received :+ item
  }

  def drain(): immutable.Vector[Any] = {
    val result = received
    received = immutable.Vector.empty
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 * No variance annotation means invariant in T.
 */
final class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Type Classes and Structural Types
// ============================================================================

/**
 * Type class for types that can be converted to token strings.
 * Replaces Python's Protocol with Scala's implicit pattern.
 */
trait Tokenizable[T] {
  def toToken(value: T): String
}

object Tokenizable {
  implicit val stringTokenizable: Tokenizable[String] = _.toString
  implicit val intTokenizable: Tokenizable[Int] = _.toString
  implicit val doubleTokenizable: Tokenizable[Double] = _.toString
  implicit val bigDecimalTokenizable: Tokenizable[BigDecimal] = _.toString
}

/**
 * Type class for types with length.
 */
trait HasLength[T] {
  def length(value: T): Int
}

object HasLength {
  implicit val stringHasLength: HasLength[String] = _.length
}

// ============================================================================
// Tokenizer Implementations (Abstract Base Trait)
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 * Uses trait instead of abstract class for Scala idioms.
 */
trait BaseTokenizer[T] {
  /**
   * Convert value to token.
   * Must be implemented by subclasses.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values using Iterator.
   * Returns lazy view for memory efficiency.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/**
 * Tokenizer for string and bytes types.
 * Demonstrates generic type bounds with type parameter constraints.
 */
final class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.String)
  }

  def tokenizeBytes(value: Array[Byte]): Token = {
    val str = new String(value, encoding)
    tokenize(str)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 * Uses BigDecimal for arbitrary precision.
 */
final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Either[Int, Either[Double, BigDecimal]]] {

  def tokenize(value: Either[Int, Either[Double, BigDecimal]]): Token = {
    val (strValue, originalType) = value match {
      case Left(intVal) =>
        (intVal.toString, "Int")
      case Right(Left(doubleVal)) =>
        (f"${doubleVal}%.${precision}f", "Double")
      case Right(Right(bigDecVal)) =>
        (f"${bigDecVal}%.${precision}f", "BigDecimal")
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }

  def tokenizeInt(value: Int): Token = tokenize(Left(value))
  def tokenizeDouble(value: Double): Token = tokenize(Right(Left(value)))
  def tokenizeBigDecimal(value: BigDecimal): Token = tokenize(Right(Right(value)))
}

/**
 * Tokenizer for date/time types using Java Time API.
 * Demonstrates union type handling with pattern matching.
 */
final class TemporalTokenizer(
    formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormatter = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE

  def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatter = formatStr.map(DateTimeFormatter.ofPattern(_)).getOrElse {
      value match {
        case Left(_) => isoFormatter
        case Right(_) => dateFormatter
      }
    }

    val strValue = value match {
      case Left(dateTime) => dateTime.format(formatter)
      case Right(date) => date.format(formatter)
    }

    Token(strValue, TokenType.Temporal)
  }

  def tokenizeDateTime(value: LocalDateTime): Token = tokenize(Left(value))
  def tokenizeDate(value: LocalDate): Token = tokenize(Right(value))
}

// ============================================================================
// Universal Tokenizer with Type Dispatch (Sealed Trait Pattern)
// ============================================================================

/**
 * Sealed trait for all tokenizable values.
 * Enables exhaustive pattern matching and type-safe dispatch.
 */
sealed trait TokenizableValue

object TokenizableValue {
  case class StringValue(value: String) extends TokenizableValue
  case class BytesValue(value: Array[Byte]) extends TokenizableValue
  case class IntValue(value: Int) extends TokenizableValue
  case class DoubleValue(value: Double) extends TokenizableValue
  case class BigDecimalValue(value: BigDecimal) extends TokenizableValue
  case class DateTimeValue(value: LocalDateTime) extends TokenizableValue
  case class DateValue(value: LocalDate) extends TokenizableValue
  case class NullValue() extends TokenizableValue
  case class StructuredValue(toTokenStr: String) extends TokenizableValue
  case class FallbackValue(value: Any) extends TokenizableValue
}

/**
 * Tokenizer that handles multiple types with pattern matching.
 * Replaces Python's duck typing with Scala's pattern matching.
 */
final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: TokenizableValue): Token = value match {
    case TokenizableValue.NullValue() =>
      Token("NULL", TokenType.Null)

    case TokenizableValue.StructuredValue(tokenStr) =>
      Token(tokenStr, TokenType.Structured)

    case TokenizableValue.StringValue(str) =>
      stringTokenizer.tokenize(str)

    case TokenizableValue.BytesValue(bytes) =>
      stringTokenizer.tokenizeBytes(bytes)

    case TokenizableValue.IntValue(int) =>
      numericTokenizer.tokenizeInt(int)

    case TokenizableValue.DoubleValue(double) =>
      numericTokenizer.tokenizeDouble(double)

    case TokenizableValue.BigDecimalValue(bd) =>
      numericTokenizer.tokenizeBigDecimal(bd)

    case TokenizableValue.DateTimeValue(dt) =>
      temporalTokenizer.tokenizeDateTime(dt)

    case TokenizableValue.DateValue(d) =>
      temporalTokenizer.tokenizeDate(d)

    case TokenizableValue.FallbackValue(any) =>
      Token(any.toString, TokenType.String, Map("fallback" -> true))
  }

  /**
   * Convenience method to tokenize Any value with reflection-free type checking.
   */
  def tokenizeAny(value: Any): Token = {
    val tokenizableValue = value match {
      case null => TokenizableValue.NullValue()
      case s: String => TokenizableValue.StringValue(s)
      case b: Array[Byte] => TokenizableValue.BytesValue(b)
      case i: Int => TokenizableValue.IntValue(i)
      case d: Double => TokenizableValue.DoubleValue(d)
      case bd: BigDecimal => TokenizableValue.BigDecimalValue(bd)
      case dt: LocalDateTime => TokenizableValue.DateTimeValue(dt)
      case d: LocalDate => TokenizableValue.DateValue(d)
      case other => TokenizableValue.FallbackValue(other)
    }
    tokenize(tokenizableValue)
  }
}

// ============================================================================
// Generic Registry with Nested Types
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Demonstrates proper handling of mutable collections in Scala.
 */
final class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: immutable.Vector[T => Option[Token]] = immutable.Vector.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry = registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers = handlers :+ handler
  }

  def process(key: String): immutable.Vector[Option[Token]] = {
    registry.get(key).map { container =>
      container.getAll.map { item =>
        handlers.iterator.map(handler => handler(item)).find(_.isDefined).flatten
      }
    }.getOrElse(immutable.Vector.empty)
  }
}

// ============================================================================
// Functor and Monad Pattern (Type Classes)
// ============================================================================

/**
 * Functor type class for tokens.
 * Replaces Python's simulated functor with proper Scala type class.
 */
trait Functor[F[_]] {
  def map[A, B](fa: F[A])(f: A => B): F[B]
}

object Functor {
  implicit val optionFunctor: Functor[Option] = new Functor[Option] {
    def map[A, B](fa: Option[A])(f: A => B): Option[B] = fa.map(f)
  }
}

/**
 * Monad type class for tokens.
 * Provides flatMap and pure operations.
 */
trait Monad[M[_]] extends Functor[M] {
  def pure[A](a: A): M[A]
  def flatMap[A, B](ma: M[A])(f: A => M[B]): M[B]
}

object Monad {
  implicit val optionMonad: Monad[Option] = new Monad[Option] {
    def pure[A](a: A): Option[A] = Some(a)
    def flatMap[A, B](ma: Option[A])(f: A => Option[B]): Option[B] = ma.flatMap(f)
    def map[A, B](fa: Option[A])(f: A => B): Option[B] = fa.map(f)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Fundamental operation for NLP and text processing.
 * Demonstrates iterative processing with metadata tracking.
 */
final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  /**
   * Process a single word into a token string.
   * Returns Option for missing/filtered tokens.
   */
  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed
        .dropWhile(punctuation.contains)
        .reverse
        .dropWhile(punctuation.contains)
        .reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase()
    }

    if (processed.length < minLength) {
      None
    } else {
      val truncated = maxLength
        .map(max => if (processed.length > max) processed.take(max) else processed)
        .getOrElse(processed)

      if (truncated.nonEmpty) Some(truncated) else None
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): immutable.Vector[Token] = {
    val words = text.split("\\s+").iterator
    var position = 0
    val builder = immutable.Vector.newBuilder[Token]

    for (word <- words) {
      processToken(word).foreach { processed =>
        val token = Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map(
            "position" -> position,
            "original" -> word
          )
        )
        builder += token
        position += 1
      }
    }

    builder.result()
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): immutable.Vector[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): immutable.Vector[(String, Int, Int)] = {
    val builder = immutable.Vector.newBuilder[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        builder += ((processed, start, end))
      }

      currentPos = end
    }

    builder.result()
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int =
    tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 * Uses self type to enable proper method chaining with generics.
 */
final class TokenizerBuilder[T] {
  private var normalizers: immutable.Vector[String => String] = immutable.Vector.empty
  private var validators: immutable.Vector[T => Boolean] = immutable.Vector.empty
  private var metadataMap: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): this.type = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): this.type = {
    validators = validators :+ validator
    this
  }

  def withMetadata(newMetadata: (String, Any)*): this.type = {
    metadataMap = metadataMap ++ newMetadata
    this
  }

  /**
   * Build the final tokenizer function.
   * Returns a function that validates, converts to string, and normalizes.
   */
  def build: T => Either[String, Token] = { value =>
    // Validate
    val validationResult = validators.iterator.find(!_.apply(value))
    if (validationResult.isDefined) {
      Left(s"Validation failed for $value")
    } else {
      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- normalizers) {
        strValue = normalizer(strValue)
      }

      Right(Token(strValue, TokenType.String, metadataMap))
    }
  }
}

// ============================================================================
// Public API Functions
// ============================================================================

object TokenizerAPI {
  /**
   * Convenience function to tokenize a single value.
   * Uses UniversalTokenizer for type dispatch.
   */
  def tokenize(value: Any): Token = {
    val tokenizer = new UniversalTokenizer()
    tokenizer.tokenizeAny(value)
  }

  /**
   * Convenience function to tokenize multiple values with a batched tokenizer.
   * Returns lazy iterator for memory efficiency.
   */
  def tokenizeBatch(tokenizer: BaseTokenizer[_], values: Iterable[Any]): Iterator[Token] = {
    // Note: In practice, specific tokenizer would be selected based on value type
    values.iterator.map {
      case s: String => tokenize(s)
      case i: Int => tokenize(i)
      case d: Double => tokenize(d)
      case other => tokenize(other)
    }
  }

  /**
   * Helper to convert a value to a Token using a specific tokenizer.
   */
  def toToken[T](tokenizer: BaseTokenizer[T])(value: T): Token =
    tokenizer.tokenize(value)

  /**
   * Helper to create a token with metadata.
   */
  def withMetadata(token: Token, metadata: (String, Any)*): Token =
    token.withMetadata(metadata: _*)
}

